package in.industrend.social;import jakarta.servlet.http.HttpServletRequest;import java.io.IOException;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/social") class SocialMediaController{record GenerateRequest(String prompt,String caption){}record PublishRequest(String caption){}private final SocialMediaService service;private final AdminAuthorizer auth;SocialMediaController(SocialMediaService service,AdminAuthorizer auth){this.service=service;this.auth=auth;}@PostMapping("/images")SocialMediaService.Post generate(@RequestBody GenerateRequest body,HttpServletRequest request){return service.create(body.prompt(),body.caption(),auth.require(request.getCookies()));}@PostMapping(value="/images/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)SocialMediaService.Post upload(@RequestPart("image")MultipartFile image,@RequestPart(value="caption",required=false)String caption,HttpServletRequest request)throws IOException{return service.upload(image.getBytes(),image.getContentType(),caption,auth.require(request.getCookies()));}@GetMapping("/images/{id}")SocialMediaService.Post status(@PathVariable UUID id,HttpServletRequest request){auth.require(request.getCookies());return service.get(id);}@GetMapping("/images/{id}/content")ResponseEntity<byte[]>content(@PathVariable UUID id,HttpServletRequest request){auth.require(request.getCookies());return ResponseEntity.ok().contentType(MediaType.parseMediaType(service.imageContentType(id))).cacheControl(CacheControl.noStore()).body(service.image(id));}@PostMapping("/images/{id}/review")SocialMediaService.Post review(@PathVariable UUID id,HttpServletRequest request){auth.require(request.getCookies());return service.review(id);}@PostMapping("/images/{id}/publish")SocialMediaService.Post publish(@PathVariable UUID id,@RequestBody PublishRequest body,HttpServletRequest request){auth.require(request.getCookies());return service.publish(id,body.caption());}}
